[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$InputDir,[Parameter(Mandatory=$true)][string]$OutJson,[string]$Filter='*.bin',[int]$MaxOutputBytes=4194304)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
function Test-Lz([byte[]]$Src){$out=[Collections.Generic.List[byte]]::new();$p=0;$done=$false;try{while(-not$done){if($p-ge$Src.Length){throw 'Unexpected end before control byte'};$flags=$Src[$p++];for($bit=0;$bit-lt 8;$bit++){if(($flags-band(1-shl$bit))-eq 0){if($p-ge$Src.Length){throw 'Unexpected end in literal'};if($out.Count+1-gt$MaxOutputBytes){throw 'Output exceeds limit'};$out.Add($Src[$p++]);continue};if($p-ge$Src.Length){throw 'Unexpected end in token'};$tag=$Src[$p++];if(($tag-band 0x80)-eq 0){if($p-ge$Src.Length){throw 'Unexpected end in long back-reference'};$len=($tag-shr 2)+3;$dist=(($tag-band 3)-shl 8)-bor$Src[$p++]}elseif(($tag-band 0x40)-eq 0){$len=(($tag-shr 4)-band 3)+2;$dist=($tag-band 15)+1}elseif($tag-eq 255){$done=$true;break}else{$len=($tag-band 63)+8;if($p+$len-gt$Src.Length){throw 'Unexpected end in run'};if($out.Count+$len-gt$MaxOutputBytes){throw 'Output exceeds limit'};for($i=0;$i-lt$len;$i++){$out.Add($Src[$p++])};continue};if($out.Count+$len-gt$MaxOutputBytes){throw 'Output exceeds limit'};if($dist-lt 1-or$dist-gt$out.Count){throw "Invalid back-reference distance $dist"};for($i=0;$i-lt$len;$i++){$out.Add($out[$out.Count-$dist])}}};if($p-ne$Src.Length){throw "Trailing input bytes: $($Src.Length-$p)"};[pscustomobject]@{valid=$true;output_bytes=$out.Count;sha256=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($out.ToArray())).ToLowerInvariant();error=$null}}catch{[pscustomobject]@{valid=$false;output_bytes=$null;sha256=$null;error=$_.Exception.Message}}}
$dir=Resolve-Path -LiteralPath $InputDir;$rows=foreach($file in Get-ChildItem -LiteralPath $dir -Filter $Filter|Sort-Object Name){$r=Test-Lz ([IO.File]::ReadAllBytes($file.FullName));[pscustomobject]@{file=$file.Name;input_bytes=$file.Length;valid=$r.valid;output_bytes=$r.output_bytes;sha256=$r.sha256;error=$r.error}}
$result=[pscustomobject]@{input_directory=$dir.Path;max_output_bytes=$MaxOutputBytes;candidate_count=@($rows).Count;valid_count=@($rows|Where-Object valid).Count;results=@($rows)};$result|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $OutJson -Encoding utf8;$result
